print("transcript entries:", len(rows)); print("keys of last:", list(rows[-1].keys()))
# print the last ~8 entries compactly: role/type + text snippets (tool names and first 600 chars of text)
def summarize(r):
    out=[]
    m=r.get("message", r)
    role=m.get("role") or r.get("type")
    content=m.get("content")
    if isinstance(content,str): out.append(content[:700])
    elif isinstance(content,list):
        for c in content:
            t=c.get("type")
            if t=="text": out.append("TEXT: "+c["text"][:700])
            elif t=="tool_use": out.append("TOOL_USE "+c.get("name","")+": "+json.dumps(c.get("input"))[:500])
            elif t=="tool_result":
                cc=c.get("content"); s=cc if isinstance(cc,str) else json.dumps(cc)
                out.append("TOOL_RESULT: "+s[:400])
    return role, out
for r in rows[-10:]:
    role,out=summarize(r)
    print("\n==",role, r.get("timestamp",""))
    for o in out: print("  ",o.replace("\n"," | ")[:700])
EOF

